import { Controller, Get, Post, HttpCode, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

// 가정: 목록 기본 쪽 크기와 최대 쪽 크기
const DEFAULT_SIZE = 20;
const MAX_SIZE = 200;
// 가정: 적용 시작월은 YYYYMM 형식
const MONTH_PATTERN = /^(19|20)\d\d(0[1-9]|1[0-2])$/;
const STATUSES = ['신청', '승인'];

function textOf(value: unknown): string {
  return typeof value === 'string' ? value.trim() : '';
}

function intOf(value: unknown, fallback: number, label: string): number {
  if (value === undefined || value === null || value === '') {
    return fallback;
  }
  const n = Number(value);
  if (!Number.isInteger(n)) {
    throw new ApiError(400, 'VALIDATION_FAILED', label + ' 값이 올바르지 않습니다.');
  }
  return n;
}

@Controller('api/v1')
export class FnSfr02002Controller {
  @Post('/withholding-adjustments')
  @HttpCode(200)
  async createWithholdingAdjustment(@Req() req: Request) {
    const user = currentUser(req);
    user.require('임직원');
    const data = checks.inputOf(req.body);
    const reason = textOf(data['reason']);
    const content = textOf(data['content']);
    const startMonth = textOf(data['startMonth']);
    if (!reason) {
      throw new ApiError(400, 'VALIDATION_FAILED', '조정 사유를 입력해 주세요.');
    }
    if (!content) {
      throw new ApiError(400, 'VALIDATION_FAILED', '조정 내용을 입력해 주세요.');
    }
    if (!MONTH_PATTERN.test(startMonth)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '적용 시작월은 YYYYMM 형식으로 입력해 주세요.');
    }
    // TODO: 마감된 월 신청 거절(422 PAYROLL_MONTH_CLOSED)은 마감 상태 출처가 없어 구현하지 못했다.
    return transaction(async (db) => {
      const rows = await db.query(
        'INSERT INTO withholding_adjustment (employee_id, reason, content, start_month, status, created_at, updated_at) ' +
          "VALUES (CAST(:userId AS bigint), :reason, :content, :startMonth, '신청', now(), now()) " +
          'RETURNING withholding_adjustment_id AS "withholdingAdjustmentId"',
        { userId: user.id, reason, content, startMonth },
      );
      return rows[0];
    });
  }

  @Get('/withholding-adjustments')
  async listWithholdingAdjustments(@Req() req: Request) {
    const user = currentUser(req);
    user.require('임직원', '급여 담당자');
    const query = checks.queryOf(req.query);
    const page = intOf(query['page'], 0, 'page');
    const size = intOf(query['size'], DEFAULT_SIZE, 'size');
    if (page < 0 || size < 1) {
      throw new ApiError(400, 'VALIDATION_FAILED', '쪽 정보가 올바르지 않습니다.');
    }
    const pageSize = Math.min(size, MAX_SIZE);
    const status = textOf(query['status']);
    const startMonth = textOf(query['startMonth']);
    if (status && !STATUSES.includes(status)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '처리 상태가 올바르지 않습니다.');
    }
    if (startMonth && !MONTH_PATTERN.test(startMonth)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '적용 시작월은 YYYYMM 형식으로 입력해 주세요.');
    }
    // 급여 담당자가 아니면 임직원으로서 본인 신청만 본다
    let isPayroll = true;
    try {
      user.require('급여 담당자');
    } catch (e) {
      isPayroll = false;
    }
    const params = {
      status: status || null,
      startMonth: startMonth || null,
      ownerId: isPayroll ? null : user.id,
      limit: pageSize,
      offset: page * pageSize,
    };
    const where =
      'WHERE (CAST(:status AS text) IS NULL OR status = CAST(:status AS text)) ' +
      'AND (CAST(:startMonth AS text) IS NULL OR start_month = CAST(:startMonth AS text)) ' +
      'AND (CAST(:ownerId AS bigint) IS NULL OR employee_id = CAST(:ownerId AS bigint)) ';
    return transaction(async (db) => {
      const items = await db.query(
        'SELECT withholding_adjustment_id AS "withholdingAdjustmentId", employee_id AS "employeeId", ' +
          'reason AS "reason", content AS "content", start_month AS "startMonth", status AS "status" ' +
          'FROM withholding_adjustment ' +
          where +
          'ORDER BY withholding_adjustment_id DESC LIMIT :limit OFFSET :offset',
        params,
      );
      const counted = await db.query(
        'SELECT COUNT(*) AS "total" FROM withholding_adjustment ' + where,
        { status: params.status, startMonth: params.startMonth, ownerId: params.ownerId },
      );
      return { items, page, size: pageSize, total: Number(counted[0].total) };
    });
  }

  @Post('/withholding-adjustments/:withholdingAdjustmentId/approve')
  @HttpCode(200)
  async approveWithholdingAdjustment(@Req() req: Request) {
    const user = currentUser(req);
    user.require('급여 담당자');
    const idText = req.params['withholdingAdjustmentId'];
    if (!/^\d+$/.test(idText)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '신청 ID가 올바르지 않습니다.');
    }
    return transaction(async (db) => {
      const rows = await db.query(
        'SELECT status AS "status", employee_id AS "employeeId" FROM withholding_adjustment ' +
          'WHERE withholding_adjustment_id = CAST(:id AS bigint) FOR UPDATE',
        { id: idText },
      );
      if (rows.length === 0) {
        throw new ApiError(404, 'WITHHOLDING_ADJUSTMENT_NOT_FOUND', '조정 신청을 찾을 수 없습니다.');
      }
      if (rows[0].status !== '신청') {
        throw new ApiError(409, 'WITHHOLDING_ADJUSTMENT_ALREADY_APPROVED', '이미 승인된 신청입니다.');
      }
      if (String(rows[0].employeeId) === String(user.id)) {
        throw new ApiError(403, 'FORBIDDEN', '본인 신청은 승인할 수 없습니다.');
      }
      // TODO: 마감된 월 승인 거절(422 PAYROLL_MONTH_CLOSED)은 마감 상태 출처가 없어 구현하지 못했다.
      const result = await db.query(
        "UPDATE withholding_adjustment SET status = '승인', approver_id = CAST(:userId AS bigint), " +
          'approved_at = now(), updated_at = now() ' +
          "WHERE withholding_adjustment_id = CAST(:id AS bigint) AND status = '신청' " +
          'RETURNING status AS "status"',
        { id: idText, userId: user.id },
      );
      return result[0];
    });
  }
}

