import { useState } from 'react';
import {
  call,
  useData,
  Badge,
  Filters,
  Band,
  DataTable,
  Pager,
  Drawer,
  Pairs,
  Tiles,
  Form,
  Field,
  TextInput,
  Select,
  RefName,
} from '../kit';
import type { PageProps, Row, Page, Column } from '../kit';

const PAGE_SIZE = 20;
const MONTH_PATTERN = /^(19|20)\d\d(0[1-9]|1[0-2])$/;
const STATUS_OPTIONS: [string, string][] = [
  ['신청', '신청'],
  ['승인', '승인'],
];

export default function FnSfr02002Page({ role, notify }: PageProps) {
  const [status, setStatus] = useState('');
  const [startMonth, setStartMonth] = useState('');
  const [applied, setApplied] = useState({ status: '', startMonth: '' });
  const [pageNo, setPageNo] = useState(0);
  const [detail, setDetail] = useState<Row | null>(null);
  const [creating, setCreating] = useState(false);
  const [reason, setReason] = useState('');
  const [content, setContent] = useState('');
  const [newMonth, setNewMonth] = useState('');

  const list = useData<Page>(
    () =>
      call<Page>('GET', '/withholding-adjustments', role, undefined, {
        status: applied.status,
        startMonth: applied.startMonth,
        page: pageNo,
        size: PAGE_SIZE,
      }),
    [role, applied, pageNo],
  );
  const pending = useData<Page>(
    () => call<Page>('GET', '/withholding-adjustments', role, undefined, { status: '신청', page: 0, size: 5 }),
    [role],
  );

  const refresh = () => {
    list.reload();
    pending.reload();
  };

  const search = () => {
    setPageNo(0);
    setApplied({ status, startMonth });
  };

  const reset = () => {
    setStatus('');
    setStartMonth('');
    setPageNo(0);
    setApplied({ status: '', startMonth: '' });
  };

  const openCreate = () => {
    setReason('');
    setContent('');
    setNewMonth('');
    setCreating(true);
  };

  const create = async () => {
    if (!reason.trim()) {
      throw new Error('조정 사유를 입력해 주세요.');
    }
    if (!content.trim()) {
      throw new Error('조정 내용을 입력해 주세요.');
    }
    if (!MONTH_PATTERN.test(newMonth.trim())) {
      throw new Error('적용 시작월은 YYYYMM 형식으로 입력해 주세요.');
    }
    await call('POST', '/withholding-adjustments', role, {
      reason: reason.trim(),
      content: content.trim(),
      startMonth: newMonth.trim(),
    });
    notify('조정 신청을 등록했습니다.');
    setCreating(false);
    refresh();
  };

  const approve = async () => {
    if (!detail) {
      return;
    }
    await call('POST', '/withholding-adjustments/' + String(detail['withholdingAdjustmentId']) + '/approve', role, {});
    notify('조정 신청을 승인했습니다.');
    setDetail(null);
    refresh();
  };

  const columns: Column[] = [
    { key: 'employeeId', label: '신청자', render: (r) => <RefName table='employee' role={role} value={r['employeeId']} /> },
    { key: 'reason', label: '조정 사유' },
    { key: 'startMonth', label: '적용 시작월' },
    { key: 'status', label: '처리 상태', render: (r) => <Badge value={r['status']} /> },
  ];

  const pendingColumns: Column[] = [
    { key: 'employeeId', label: '신청자', render: (r) => <RefName table='employee' role={role} value={r['employeeId']} /> },
    { key: 'startMonth', label: '적용 시작월' },
  ];

  const data = list.data;

  return (
    <div className='bento'>
      <section className='box span-4'>
        <h2>처리 대기</h2>
        <Tiles items={[['승인 대기 신청', pending.data ? pending.data.total : 0]]} />
        <DataTable
          columns={pendingColumns}
          rows={pending.data ? pending.data.items : []}
          onRowClick={(r) => setDetail(r)}
          empty='대기 중인 신청이 없습니다.'
        />
      </section>
      <section className='box span-8'>
        <h2>조정 신청 목록</h2>
        <Filters onSearch={search} onReset={reset}>
          <Field label='처리 상태'>
            <Select value={status} onChange={setStatus} options={STATUS_OPTIONS} placeholder='전체' />
          </Field>
          <Field label='적용 시작월' hint='YYYYMM'>
            <TextInput value={startMonth} onChange={setStartMonth} />
          </Field>
        </Filters>
        <Band total={data ? data.total : 0}>
          {role === '임직원' && (
            <button type='button' onClick={openCreate}>
              조정 신청
            </button>
          )}
        </Band>
        {list.error && <p>{list.error}</p>}
        <DataTable columns={columns} rows={data ? data.items : []} onRowClick={(r) => setDetail(r)} empty='조정 신청이 없습니다.' />
        <Pager page={pageNo} size={PAGE_SIZE} total={data ? data.total : 0} onPage={setPageNo} />
      </section>

      {creating && (
        <Drawer title='원천징수세액 조정 신청' onClose={() => setCreating(false)}>
          <Form onSubmit={create} submit='신청'>
            <Field label='조정 사유' required wide>
              <TextInput value={reason} onChange={setReason} multiline />
            </Field>
            <Field label='조정 내용' required wide>
              <TextInput value={content} onChange={setContent} multiline />
            </Field>
            <Field label='적용 시작월' required hint='YYYYMM 형식'>
              <TextInput value={newMonth} onChange={setNewMonth} placeholder='202601' />
            </Field>
          </Form>
        </Drawer>
      )}

      {detail && (
        <Drawer title='조정 신청 상세' onClose={() => setDetail(null)}>
          <Pairs
            items={[
              ['신청자', <RefName table='employee' role={role} value={detail['employeeId']} />],
              ['조정 사유', String(detail['reason'] ?? '')],
              ['조정 내용', String(detail['content'] ?? '')],
              ['적용 시작월', String(detail['startMonth'] ?? '')],
              ['처리 상태', <Badge value={detail['status']} />],
            ]}
          />
          {detail['status'] === '신청' && role === '급여 담당자' && (
            <Form onSubmit={approve} submit='승인' note='승인하면 급여 계산 기준에 반영됩니다.' />
          )}
        </Drawer>
      )}
    </div>
  );
}
